<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarParametro, guardarParametro, listarParametros } from '../services/parametros'
import type { ParametroCalidad, ParametroPayload, UnidadParametro } from '../interfaces/parametros.interface'
const records=ref<ParametroCalidad[]>([]),units=ref<UnidadParametro[]>([]),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),form=reactive<ParametroPayload>({nombre:'',codigo:'',unidad_id:null})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarParametros(query.value,target);records.value=r.data;units.value=r.unidades;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:ParametroCalidad){editing.value=item?.id??null;Object.assign(form,item?{nombre:item.nombre,codigo:item.codigo,unidad_id:item.unidad_id}:{nombre:'',codigo:'',unidad_id:null});modal.value=true}
async function save(){if(!form.nombre.trim()||!form.codigo.trim()||!form.unidad_id){error.value='Complete el nombre, código y unidad.';return}saving.value=true;error.value='';try{await guardarParametro({nombre:form.nombre.trim(),codigo:form.codigo.trim(),unidad_id:form.unidad_id},editing.value??undefined);modal.value=false;success.value=`Parámetro ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:ParametroCalidad){if(item.resultados_count){error.value='El parámetro no se puede eliminar porque está vinculado a resultados.';return}if(!confirm(`¿Eliminar el parámetro ${item.nombre}?`))return;try{await eliminarParametro(item.id);success.value='Parámetro eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Control de Calidad / Parámetros</nav><header class="hero"><div class="mark">PC</div><div><small>DANA · CONTROL DE CALIDAD</small><h1>Parámetros de control</h1><p>Administra las variables analíticas utilizadas en los resultados.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo parámetro</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><div><small>FILTROS DE BÚSQUEDA</small><b>Buscar parámetros</b></div><input v-model.trim="query" placeholder="Nombre o código"><button>Buscar</button><button type="button" class="soft" @click="query='';load(1)">Limpiar</button></form><div v-if="loading" class="empty">Cargando parámetros…</div><div v-else-if="!records.length" class="empty">No se encontraron parámetros.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><span>⌁</span><div><small>PARÁMETRO #{{item.id}}</small><h2>{{item.nombre}}</h2></div><em>{{item.codigo}}</em></header><div class="unit"><small>UNIDAD DE MEDIDA</small><b>{{item.unidad}}</b></div><dl><div><dt>Creado</dt><dd>{{item.created_at}}</dd></div><div><dt>Resultados vinculados</dt><dd>{{item.resultados_count}}</dd></div></dl><footer><button class="edit" @click="open(item)">Modificar</button><button class="delete" :disabled="!!item.resultados_count" :title="item.resultados_count?'Vinculado a resultados':''" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">PC</div><div><small>CONTROL DE CALIDAD</small><h2>{{editing?'Modificar':'Registrar'}} parámetro</h2></div><button type="button" @click="modal=false">×</button></header><label>Nombre *<input v-model="form.nombre" maxlength="45" required></label><div class="row"><label>Código *<input v-model="form.codigo" maxlength="45" placeholder="Ej.: CLR" required></label><label>Unidad *<select v-model="form.unidad_id" required><option :value="null">Seleccione</option><option v-for="item in units" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label></div><p>El nombre debe ser único. Una unidad solo puede estar asociada a un parámetro según la regla actual de Laravel.</p><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
